from pwn import *
import numpy as np
from collections import Counter
import json

def analyze_pubkey(coeffs):
    coeffs = np.array(coeffs)

    analysis = {}
    analysis["Basic Statistics"] = {
        "Mean": float(np.mean(coeffs)),
        "Median": float(np.median(coeffs)),
        "Std Dev": float(np.std(coeffs)),
        "Min": int(np.min(coeffs)),
        "Max": int(np.max(coeffs))
    }

    q = 128
    valid_range = [-q//2, q//2]
    out_of_range = [x for x in coeffs if x < valid_range[0] or x > valid_range[1]]
    analysis["Range Analysis"] = {
        "Out of range count": len(out_of_range),
        "Out of range values": out_of_range
    }

    value_counts = Counter(coeffs)
    analysis["Value Distribution"] = {
        "Most common values": value_counts.most_common(5)
    }

    # Check for consecutive same values
    consecutive = []
    current_val = coeffs[0]
    current_count = 1
    for i in range(1, len(coeffs)):
        if coeffs[i] == current_val:
            current_count += 1
        else:
            if current_count > 1:
                consecutive.append((int(current_val), current_count))
            current_val = coeffs[i]
            current_count = 1

    analysis["Pattern Analysis"] = {
        "Consecutive patterns": consecutive[:5]
    }

    diffs = np.diff(coeffs)
    analysis["Coefficient Relationships"] = {
        "Mean difference": float(np.mean(diffs)),
        "Max difference": int(np.max(diffs)),
        "Min difference": int(np.min(diffs))
    }

    # GCD of non-zero coefficients
    from math import gcd
    from functools import reduce
    nonzero = [abs(int(x)) for x in coeffs if x != 0]
    if nonzero:
        gcd_all = reduce(gcd, nonzero)
        analysis["GCD Analysis"] = {
            "GCD of non-zero coefficients": gcd_all
        }

    analysis["Additional Statistics"] = {
        "Zero coefficients": int(np.sum(coeffs == 0)),
        "Positive coefficients": int(np.sum(coeffs > 0)),
        "Negative coefficients": int(np.sum(coeffs < 0))
    }

    # Check if coefficients are symmetric
    n = len(coeffs)
    is_symmetric = True
    for i in range(n//2):
        if coeffs[i] != coeffs[n-1-i]:
            is_symmetric = False
            break
    analysis["Symmetry"] = {
        "Is symmetric": is_symmetric
    }

    return analysis

# Connect to server and get pubkey
conn = remote('crypto.chal.csaw.io', 5000)

# Wait for the public key
pubkey = None
while True:
    try:
        line = conn.recvline().decode().strip()
        data = json.loads(line)
        if 'public_key' in data:
            pubkey = data['public_key']
            break
    except:
        continue

conn.close()

# Analyze the public key
if pubkey:
    print("Public key received. Analyzing...")
    results = analyze_pubkey(pubkey)
    print("\nAnalysis Results:")
    print(json.dumps(results, indent=2))

